window.bookSummaryJSON = "<p><b>A must-listen collection of 15 bibliomysteries by best-selling and award-winning authors</b></p> <p><i>Bibliomysteries Volume 2</i> includes:</p> <p>\"Remaindered\" by Peter Lovesey</p> <p>\"The Compendium of Srem\" by F. Paul Wilson</p> <p>\"The Sequel\" by R. L. Stine</p> <p>\"Mystery, Inc.\" by Joyce Carol Oates</p> <p>And many others </p> <p>Copyright 2012 by Jeffery Deaver (\"An Acceptable Sacrifice\"); copyright 2012 by C. J. Box (\"Pronghorns of the Third Reich\"); copyright 2011 by Ken Bruen (\"The Book of Virtue\"); copyright 2011 by Reed Farrel Coleman (\"The Book of Ghosts\"); copyright 2013 by Peter Blauner (\"The Final Testament\"); copyright 2013 by Thomas H. Cook (\"What's in a Name?”); copyright 2012 by Loren D. Estleman (\"Book Club\"); copyright 2012 by William Link (\"Death Leaves a Bookmark\"); copyright 2012 by Laura Lippman (\"The Book Thing\"); copyright 2011 by Anne Perry (\"The Scroll\"); copyright 2013 by Mickey Spillane and Max Allan Collins (\"It's in the Book\"); copyright 2013 by Andrew Taylor (\"The Long Sonata of the Dead\"); copyright 2013 by David Bell (\"Rides a Stranger\")</p>"; 
